ANNOTATIONS = [
    (7, 'after_block', r'''文件定位：按住说话的语音输入 hook。终端 auto-repeat 事件流当「按住/松开」信号用（没有 keyup 事件可听），录音走平台原生模块（macOS）或 SoX，识别走 Anthropic voice_stream 端点。整个文件的主线是「怎么在松键瞬间可靠地结束录音」以及「识别结果为空时怎么分清是哪种空」。'''),
    (30, 'after', r'''语言归一化小节：STT 只认 BCP-47 码，用户设置里可能是语言全名。'''),
    (41, 'after_block', r'''这张表同时收录英文名和母语名（español/日本語/한국어），因为用户 settings.language 里填什么的都有。硬约束：表必须是服务端 GrowthBook 配置（speech_to_text_voice_stream_config）supported_language_codes 的子集——CLI 多发一个码，服务端直接 WebSocket 1008 关连接，语音整个坏掉。认不出的语言回落 DEFAULT_STT_LANGUAGE，录音至少还能用。'''),
    (92, 'after_block', r'''与上一张表分开维护：这张是「已确认服务端支持」的码集合，normalizeLanguageForSTT 的快速路径直接查它。'''),
    (120, 'after_block', r'''归一化四级回落链：原样命中 → 语言名查表 → 取 BCP-47 主标签（zh-CN → zh）→ 兜底英语。非空但不支持时不静默——fellBackFrom 带上原始输入，调用方可以弹警告，用户不会以为自己的中文被识别了。'''),
    (139, 'after_block', r'''懒加载的原因不是启动速度而是权限：macOS 上加载原生录音模块会触发 TCC 麦克风授权弹窗，必须等用户真要用语音时才加载。'''),
    (160, 'after', r'''RELEASE_TIMEOUT_MS = 200ms。终端按住键时 auto-repeat 每 30-80ms 触发一次；超过 200ms 没有新事件就判定松键。取 200 是为了盖住抖动同时不觉得钝。'''),
    (172, 'after', r'''FIRST_PRESS_FALLBACK_MS = 2000，给「组合键首次按下」场景用。注意这里等的是 OS 初始重复**延迟**（macOS 滑块拉到最长时约 2s），不是重复速率，所以比 REPEAT_FALLBACK_MS 大一个量级。'''),
    (177, 'after', r'''focus 模式下 5s 没说话就拆会话，把 WebSocket 连接还给服务端；下次聚焦（失焦→重新获得焦点）重新 arm。'''),
    (185, 'after', r'''16 位 PCM 的 RMS 归一化到 0-1，外面再套一次 sqrt：响度感知是对数的，不开根号的话小声段全挤在波形底部，16 根柱子看起来像死的。'''),
    (217, 'after', r'''seenRepeatRef：见到第二次击键（auto-repeat 开始）才算数。macOS 初始重复延迟约 500ms，这期间松键判定计时器不能 arm，否则用户正常按住就被切断了。'''),
    (223, 'after', r'''focusTriggeredRef 区分会话是终端焦点拉起的还是按键拉起的：焦点拉起的会话在失焦时结束，不受松键逻辑管。'''),
    (231, 'after', r'''silenceTimedOutRef 防「静默超时拆掉后焦点效应立刻又拉起来」的死循环；失焦时清零，让下一个聚焦周期重新 arm。'''),
    (237, 'after', r'''sessionGenRef 是本文件最重要的 ref。每次 startRecordingSession 自增，所有异步回调闭包捕获自己的代际，发现代际过期就 bail——否则上一个会话慢连接的僵尸 WS 会在新会话中途改写 connectionRef。'''),
    (246, 'after', r'''fullAudioRef 存整场音频做静默丢包重放：约 1% 的会话会撞上「粘性坏 pod」（anthropics/anthropic#287008），收音频但零转写。上限 32KB/s × 60s ≈ 2MB。'''),
    (252, 'after', r'''attemptGenRef 比 sessionGenRef 低一级：同一次会话内的重连（早错重试、静默重放）各自算 attempt。onError 靠它吞掉被取代连接的尾部报错，只放行当前 attempt 的真失败。'''),
    (257, 'after', r'''focusFlushedCharsRef：focus 模式每段 final 立即注入并清空 accumulatedRef，不记这个数的话遥测里 transcriptChars=0 会被误判成静默丢包。'''),
    (260, 'after', r'''hasAudioSignalRef 区分「麦克风静音/没权限」和「有声音但没识别出语音」——两种给用户的报错文案完全不同。'''),
    (266, 'after', r'''everConnectedRef 与 connectionRef 的区别：cleanup() 会把后者置空，但 effect 清理顺序竞态（Effect 3 先于 Effect 2 的 finishRecording 跑）时前者还活着，遥测的 wsConnected 维度和报错分支都靠它。'''),
    (284, 'before', r'''cleanup：一键作废整个会话。sessionGenRef 先自增让所有在途回调（主连接 isStale、重放 isStale、finishRecording 续延）全部失效——少了这一步，语音被关掉后重放窗口里的旧回调还能开一条 WS 把转写注进来。'''),
    (322, 'before', r'''finishRecording：松键/焦点丢失/外部结束的统一出口。第一原则是所有 ref 值在异步边界**之前**采完——finalize 等待期间用户可能又按键开新会话，把这些 ref 重置，那采到的就是新会话的数。'''),
    (365, 'before', r'''finalize 后必须等 WebSocket 真正关闭再读累计转写：关闭处理器会把还没上报的 interim 文本提为 final，不等它就丢最后一句。'''),
    (454, 'after', r'''静默重放的六个条件全部满足才触发：服务端收过音频（wsConnected）+ 麦克风有真实信号（hadAudioSignal）+ finalize 超时无转写 + 不是焦点会话 + 焦点模式没 flush 过 + 本次还没重放过 + 缓冲区非空。250ms 退避清同 pod 快速重连竞态。'''),
    (529, 'after_block', r'''enabled 时才 import，而且绝不预加载：require audio-capture.node 是同步 dlopen CoreAudio/AudioUnit，会堵事件循环 1s（热）到 8s（冷 coreaudiod）。setImmediate 救不了——它只让出一个 tick，dlopen 照样堵。所以这笔账记在第一次按键上。'''),
    (542, 'before', r'''armFocusSilenceTimer：焦点会话的静默看门狗。说话（final 或 interim）就重置，5s 无动静拆会话。注意 setTimeout 额外参数把 ref 和 finishRecording 全传进去——避免闭包捕获旧值。'''),
    (575, 'after_block', r'''焦点驱动录音：终端获得焦点就录、失去焦点就停，服务「多 claude 军团」工作流—— Voice 输入跟着窗口焦点走，人切换到哪个窗就说哪条命令。'''),
    (632, 'after', r'''startRecordingSession：一场录音的完整建立过程（可用性预检 → 起录音 → 连 WS → 缓冲区管理）。'''),
    (648, 'after', r'''先同步切 recording 再 await，因为有两个读者在同一 tick 内同步读状态：useVoiceIntegration 的空格按住守卫（看到 idle 会清 isSpaceHoldActiveRef，空格 auto-repeat 就漏进文本输入，100% 复现）和下面的 idle 重入检查。PR #20873 review 的教训。'''),
    (658, 'after', r'''可用性预检失败（没麦克风权限、没录音工具）立即 cleanup 回 idle，不让用户对着一个假录音界面说话。'''),
    (686, 'after', r'''录音立即开始、音频进缓冲区，不等 OAuth + WS 握手——这消掉了 1-2s 的启动延迟，按下的瞬间就在录。'''),
    (731, 'after', r'''startRecording 的两个回调：数据回调（缓冲/直发/电平/信号检测四合一）和外部结束回调（设备错误当成松键处理）。silenceDetection: false 是因为静音检测由焦点计时器那套管，不重复。'''),
    (759, 'after', r'''recording_started 事件的维度设计：语言是不是默认、有没有回落、Intl 系统语言（有界集合，不是用户文本，所以能安全上报；Intl 失败就省略不重试）。'''),
    (768, 'after_block', r'''早错重试：连接建立后、任何转写到达前报错，大概率是瞬时竞态——CE 代理拒绝快速重连（同 pod 碰撞）或 Deepgram 上游在自己的拆除窗口内挂（#287008 里表现为 TranscriptError）。250ms 退避同时清这两种。致命错误（Cloudflare 人机挑战、鉴权拒绝）重试结果一样，直接透传。'''),
    (841, 'before', r'''onError 两级过滤：isStale 吞旧会话的，attemptGen 不匹配吞被取代 attempt 的（conn 1 重试调度后的尾部关闭、当前 conn 报错后紧跟的 1006 关闭）。剩下才走重试或上报。'''),
    (975, 'after', r'''onReady 做两件事：把连接期攒的音频合并成约 1s 的帧 flush 出去（减少 WS 帧数，两端都省），以及在见过 auto-repeat 的前提下重新 arm 松键计时器。'''),
    (1007, 'after', r'''连接 promise resolve 后还有两道闸：代际过期就直接关（慢连接场景）；用户已经松键（状态离开 recording）也关——onReady 可能在松键之后才跑。'''),
    (1010, 'after', r'''先 gather 语音关键词（快、无模型调用）再连 WS，这样连接请求能带上 keyterms，少一轮往返。'''),
    (1021, 'after_block', r'''handleKeyEvent 在每次击键时被调用（包括 auto-repeat）。核心设计：第一次击键立即开始录音（消启动延迟），松键计时器只在确认 auto-repeat 启动后才 arm；600ms 内没见到重复就当成「用户轻点一下就松了」，用 fallback 补偿 arm。'''),
    (1052, 'before', r'''idle 分支：立即开会话 + 600ms fallback 计时器（等不到 auto-repeat 就替它 arm 松键计时）。'''),
    (1101, 'after', r'''recording 分支：第二次及以后的击键说明 auto-repeat 已启动——置 seenRepeat、清掉 fallback，之后每次击键重置 200ms 松键计时器。'''),
    (1129, 'after', r'''这个 effect 只在 enabled 变化或卸载时跑，不跟状态走——否则每次 idle/recording 切换都白跑一次 cleanup。'''),
]
